create or replace function public.nail_2nya_create_booking(p_service_id uuid,p_start_at timestamptz,p_name text,p_phone text,p_instagram text default null,p_email text default null,p_notes text default null) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v_service public.nail_2nya_services%rowtype; v_customer uuid; v_appt uuid; v_token text; v_ref text; v_date date; v_tz text; v_valid boolean; begin if nullif(trim(p_name),'') is null or nullif(trim(p_phone),'') is null then return jsonb_build_object('ok',false,'code','invalid_customer'); end if; select * into v_service from public.nail_2nya_services where id=p_service_id and active=true and booking_available=true; if not found then return jsonb_build_object('ok',false,'code','service_unavailable'); end if; select timezone into v_tz from public.nail_2nya_business_profile order by created_at limit 1; v_date:=(p_start_at at time zone v_tz)::date; select exists(select 1 from public.nail_2nya_available_slots(v_date,p_service_id) s where s.slot_start=p_start_at) into v_valid; if not v_valid then return jsonb_build_object('ok',false,'code','slot_taken'); end if; v_appt:=gen_random_uuid(); v_ref:=upper(substr(replace(v_appt::text,'-',''),1,8)); v_token:=encode(extensions.gen_random_bytes(32),'hex'); begin insert into public.nail_2nya_customers(name,phone,instagram_username,email) values(trim(p_name),trim(p_phone),nullif(trim(p_instagram),''),nullif(trim(p_email),'')) returning id into v_customer; insert into public.nail_2nya_appointments(id,booking_reference,service_id,customer_id,start_at,end_at,reserved_start_at,reserved_end_at,status,customer_notes,source) values(v_appt,v_ref,p_service_id,v_customer,p_start_at,p_start_at+make_interval(mins=>v_service.duration_minutes),p_start_at-make_interval(mins=>v_service.buffer_before),p_start_at+make_interval(mins=>(v_service.duration_minutes+v_service.buffer_after)),'pending',nullif(trim(p_notes),''),'customer'); exception when exclusion_violation then return jsonb_build_object('ok',false,'code','slot_taken'); end; insert into public.nail_2nya_booking_tokens(appointment_id,token_hash) values(v_appt,extensions.digest(v_token::bytea,'sha256')); return jsonb_build_object('ok',true,'appointment_id',v_appt,'reference',v_ref,'management_token',v_token,'status','pending','start_at',p_start_at,'end_at',p_start_at+make_interval(mins=>v_service.duration_minutes)); end; $$;